-- Remove the made-up numbers from the demo catalogue (decided 2026-11-06): product star ratings, review counts and
-- "price drop %" were generated by 01-catalog.sql, and so were store ratings. The site hides stars and drop tags when
-- these are empty. Real values come back only from a real source (store feed, Amazon API, our own price history).
-- Reversible: the old values are kept in demo_ratings first. Safe to run twice.
begin;
create table if not exists public.demo_ratings as
  select 'product'::text as kind, id, rating, reviews, drop_pct from public.products where false;
alter table public.demo_ratings enable row level security;           -- backup only: no API access
insert into public.demo_ratings
  select 'product', id, rating, reviews, drop_pct from public.products
  where (rating is not null or reviews <> 0 or drop_pct <> 0)
    and not exists (select 1 from public.demo_ratings d where d.kind = 'product' and d.id = products.id);
insert into public.demo_ratings
  select 'store', id, rating, reviews, null from public.stores
  where (rating is not null or reviews <> 0)
    and not exists (select 1 from public.demo_ratings d where d.kind = 'store' and d.id = stores.id);
update public.products set rating = null, reviews = 0, drop_pct = 0, base_usd = null
  where rating is not null or reviews <> 0 or drop_pct <> 0 or base_usd is not null;
update public.stores set rating = null, reviews = 0 where rating is not null or reviews <> 0;
commit;
select (select count(*) from public.products where rating is not null or drop_pct <> 0) as products_with_numbers,
       (select count(*) from public.stores where rating is not null) as stores_with_rating,
       (select count(*) from public.demo_ratings) as backed_up;
